CREATE UNIQUE INDEX "ingest_runs_active_user_idx" ON "ingest_runs" USING btree ("user_id") WHERE "ingest_runs"."finished_at" is null;--> statement-breakpoint
CREATE VIEW "public"."feedback_topics" AS (select "feedback_items"."user_id", t.topic as "topic", COUNT(*) as "cnt" from "feedback_items" inner join "feedback_analyses" on "feedback_analyses"."feedback_item_id" = "feedback_items"."id" inner join LATERAL jsonb_array_elements_text("feedback_analyses"."topics") AS t(topic) on true group by "feedback_items"."user_id", t.topic);--> statement-breakpoint
CREATE VIEW "public"."feedback_trend" AS (select "feedback_items"."user_id", DATE("feedback_items"."created_at") as "day", COUNT(*) as "cnt", COUNT(*) - LAG(COUNT(*), 1, COUNT(*)) OVER (PARTITION BY "feedback_items"."user_id" ORDER BY DATE("feedback_items"."created_at")) as "delta" from "feedback_items" inner join "feedback_analyses" on "feedback_analyses"."feedback_item_id" = "feedback_items"."id" group by "feedback_items"."user_id", DATE("feedback_items"."created_at"));--> statement-breakpoint
CREATE VIEW "public"."high_severity_analyses" AS (select "user_id", "summary", "severity_score", "created_at" from "feedback_analyses" where "feedback_analyses"."severity_score" >= 4);